package io.github.zeehan2005.scoremuse.data.get.qq

import android.util.Base64
import timber.log.Timber
import java.io.ByteArrayInputStream
import java.nio.charset.Charset
import java.util.Locale
import java.util.zip.Inflater
import java.util.zip.InflaterInputStream

/**
 * QQ 音乐 QRC 歌词解密器
 * 
 * 这个解密器实现了 QQ 音乐专有的 QRC 歌词加密算法。
 * QQ 音乐的加密流程非常复杂，包含多层编码和解密：
 * 
 * 加密流程（反向即为解密）：
 * 1. 原始歌词文本
 * 2. 可能使用 GBK/GB18030 编码（中文歌词）
 * 3. Zlib 压缩
 * 4. 3DES 加密（非标准实现）
 * 5. Hex 编码（十六进制字符串）
 * 
 * 这个工具与 Unilyric 的非标准 DES 实现对齐，确保兼容性。
 */
object QqMusicQrcCrypto {
    /** DES 加密参数（与非标准实现对齐） */
    private const val ROUNDS = 16          // 加密轮数
    private const val SUB_KEY_SIZE = 6     // 子密钥大小
    private const val DES_BLOCK_SIZE = 8   // DES 块大小（8 字节）

    private val codec = QqMusicCodec()     // QQ 音乐专用的编解码器

    /**
     * 解密 QQ 音乐的 QRC 歌词
     * 
     * 这是获取 QQ 音乐逐字歌词的核心方法。解密过程非常复杂，需要处理多种情况：
     * 
     * 主要流程：
     * 1. 优先尝试使用 Rust 原生解码器（性能更好，更可靠）
     * 2. 如果失败则回退到 Kotlin 实现
     * 3. Hex 解码 → 3DES 解密 → Zlib 解压 → UTF-8/GBK 解码
     * 4. 特殊处理：Base64 二次解码、BOM 头移除、字符集回退
     * 
     * @param encryptedText Hex 编码的加密歌词字符串
     * @return 解密后的歌词文本
     */
    fun decryptQrcHex(encryptedText: String): String {
        Timber.d("[QqMusicQrcCrypto] Starting Hex+3DES+Zlib decryption, input length: ${encryptedText.length}")
        Timber.v("[QqMusicQrcCrypto] Input preview (first 200 chars): ${encryptedText.take(200)}")

        // 优先使用 Rust 原生解码器（与上游 Unilyric 逻辑一致，性能更好）
        runCatching {
            QqMusicQrcNative.decryptQrcHex(encryptedText)
        }.getOrNull()?.let { nativeResult ->
            if (nativeResult.isNotBlank()) {
                Timber.d("[QqMusicQrcCrypto] Decoded using native Rust decoder (length=${nativeResult.length})")
                return nativeResult
            }
        }

        Timber.i("[QqMusicQrcCrypto] Native Rust decoder returned empty or failed; falling back to Kotlin implementation")

        val encryptedBytes = decodeHex(encryptedText)  // Hex 字符串转字节数组
        Timber.d("[QqMusicQrcCrypto] After Hex decode: ${encryptedBytes.size} bytes")

        // 确保数据长度是 DES 块大小的倍数（8 字节）
        require(encryptedBytes.size % DES_BLOCK_SIZE == 0) {
            "Encrypted data length must be a multiple of $DES_BLOCK_SIZE"
        }

        /** 逐块进行 3DES 解密 */
        val decrypted = ByteArray(encryptedBytes.size)
        var offset = 0
        while (offset < encryptedBytes.size) {
            codec.decryptBlock(encryptedBytes, offset, decrypted, offset)
            offset += DES_BLOCK_SIZE
        }

        Timber.d("[QqMusicQrcCrypto] After 3DES decrypt: ${decrypted.size} bytes, first 32 bytes: ${decrypted.take(32).joinToString(",") { "%02X".format(it) }}")

        // 特殊情况处理：某些 QQ 歌词在 3DES 解密后不是 zlib 压缩数据，而是 Base64 或纯文本
        // 如果解密后的内容看起来像可打印字符，尝试 Base64 解码
        if (looksLikeMostlyPrintable(decrypted)) {
            val candidate = String(decrypted, Charsets.UTF_8).trim()
            Timber.d("[QqMusicQrcCrypto] Decrypted output looks like text (len=${candidate.length})")
            Timber.v("preview=${candidate.take(200)}")
            val base64Regex = Regex("^[A-Za-z0-9+/=\\s]+$")
            if (candidate.length % 4 == 0 && base64Regex.matches(candidate)) {
                try {
                    val decoded = Base64.decode(candidate, Base64.DEFAULT)
                    val decodedText = String(decoded, Charsets.UTF_8)
                    Timber.d("[QqMusicQrcCrypto] Interpreted decrypted output as Base64")
                    Timber.v("decoded text preview=${decodedText.take(200)}")
                    return decodedText  // Base64 解码成功，直接返回
                } catch (e: Exception) {
                    Timber.w("[QqMusicQrcCrypto] Base64 decode of decrypted content failed $e")
                }
            }
        }

        val decompressed = if (decrypted.isNotEmpty() && decrypted[0] != 0x78.toByte()) {
            Timber.i("[QqMusicQrcCrypto] First byte is 0x${"%02X".format(decrypted[0])} (not 0x78), attempting to locate zlib header")
            attemptDecompressFromPossibleZlibOffset(decrypted)
        } else {
            decompress(decrypted)
        }
        Timber.d("[QqMusicQrcCrypto] After Zlib decompress: ${decompressed.size} bytes")
        Timber.v("[QqMusicQrcCrypto] Decompressed preview (first 200 chars): ${String(decompressed.take(200).toByteArray(), Charsets.UTF_8)}")

        val payload = if (
            decompressed.size >= 3 &&
            decompressed[0] == 0xEF.toByte() &&
            decompressed[1] == 0xBB.toByte() &&
            decompressed[2] == 0xBF.toByte()
        ) {
            Timber.d("[QqMusicQrcCrypto] UTF-8 BOM detected, removing first 3 bytes")
            decompressed.copyOfRange(3, decompressed.size)
        } else {
            decompressed
        }

        val utf8Result = payload.toString(Charsets.UTF_8)

        // If UTF-8 decoding produces replacement characters, QQ may be using a different legacy
        // encoding (e.g. GBK/GB18030). In that case, attempt a fallback decode.
        if (utf8Result.contains('\uFFFD')) {
            Timber.i("[QqMusicQrcCrypto] UTF-8 decoding produced replacement chars; retrying with GB18030")
            try {
                val gb18030 = payload.toString(Charset.forName("GB18030"))
                Timber.d("[QqMusicQrcCrypto] Final result length (GB18030): ${gb18030.length}")
                Timber.v("preview (first 300 chars): ${gb18030.take(300)}")
                return gb18030
            } catch (e: Exception) {
                Timber.i("[QqMusicQrcCrypto] GB18030 decode failed; falling back to UTF-8 $e")
            }
        }

        Timber.d("[QqMusicQrcCrypto] Final result length: ${utf8Result.length}")
        Timber.v("preview (first 300 chars): ${utf8Result.take(300)}")
        return utf8Result
    }

    private fun decodeHex(value: String): ByteArray {
        val clean = value.trim()
        require(clean.length % 2 == 0) { "Invalid hex string length" }
        val out = ByteArray(clean.length / 2)
        var i = 0
        while (i < clean.length) {
            val hi = clean[i].digitToIntOrNull(16) ?: error("Invalid hex string")
            val lo = clean[i + 1].digitToIntOrNull(16) ?: error("Invalid hex string")
            out[i / 2] = ((hi shl 4) or lo).toByte()
            i += 2
        }
        return out
    }

    private fun decompress(data: ByteArray): ByteArray {
        return try {
            InflaterInputStream(ByteArrayInputStream(data)).use { it.readBytes() }
        } catch (e: Exception) {
            Timber.i("[QqMusicQrcCrypto] Zlib decompression failed, retrying as raw deflate $e")
            /** Some QQ QRC payloads appear to be raw DEFLATE without zlib headers. */
            val inflater = Inflater(true)
            try {
                InflaterInputStream(ByteArrayInputStream(data), inflater).use { it.readBytes() }
            } finally {
                inflater.end()
            }
        }
    }

    private fun looksLikeMostlyPrintable(bytes: ByteArray): Boolean {
        if (bytes.isEmpty()) return false
        val printable = bytes.count { b ->
            val c = b.toInt() and 0xFF
            (c in 0x20..0x7E) || c == 0x0A || c == 0x0D || c == 0x09
        }
        return printable.toDouble() / bytes.size >= 0.75
    }

    private fun attemptDecompressFromPossibleZlibOffset(data: ByteArray): ByteArray {
        /**
         * zlib header validity check: (CMF*256 + FLG) % 31 == 0
         * CMF is fixed to 0x78 for deflate, but FLG varies.
         */
        val candidateOffsets = data.withIndex().filter { it.value == 0x78.toByte() }.map { it.index }
        Timber.d("[QqMusicQrcCrypto] Found ${candidateOffsets.size} potential 0x78 zlib start bytes")

        for (offset in candidateOffsets) {
            if (offset + 1 >= data.size) continue
            val second = data[offset + 1].toInt() and 0xFF
            val combined = (0x78 shl 8) or second
            val valid = combined % 31 == 0
            Timber.d("[QqMusicQrcCrypto] Candidate @ $offset: header=0x78 0x${"%02X".format(second)} valid=$valid")
            if (!valid) continue

            try {
                Timber.d("[QqMusicQrcCrypto] Attempt decompress at offset $offset (header=0x78 0x${"%02X".format(second)})")
                return decompress(data.copyOfRange(offset, data.size))
            } catch (e: Exception) {
                Timber.w("[QqMusicQrcCrypto] Decompress attempt failed at offset $offset $e")
            }
        }

        // As a last resort, try decompress from the very start using raw deflate
        Timber.i("[QqMusicQrcCrypto] No valid zlib header found; falling back to raw deflate from start")
        val inflater = Inflater(true)
        return try {
            InflaterInputStream(ByteArrayInputStream(data), inflater).use { it.readBytes() }
        } finally {
            inflater.end()
        }
    }

    private class QqMusicCodec {
        private val decryptSchedule: Array<Array<ByteArray>> = arrayOf(
            CustomDes.keySchedule(CustomDes.KEY_3, CustomDes.Mode.Decrypt),
            CustomDes.keySchedule(CustomDes.KEY_2, CustomDes.Mode.Encrypt),
            CustomDes.keySchedule(CustomDes.KEY_1, CustomDes.Mode.Decrypt)
        )

        fun decryptBlock(input: ByteArray, inputOffset: Int, output: ByteArray, outputOffset: Int) {
            val temp1 = ByteArray(8)
            val temp2 = ByteArray(8)
            val block = input.copyOfRange(inputOffset, inputOffset + 8)
            CustomDes.desCrypt(block, temp1, decryptSchedule[0])
            CustomDes.desCrypt(temp1, temp2, decryptSchedule[1])
            CustomDes.desCrypt(temp2, output, decryptSchedule[2], outputOffset)
        }
    }

    private object CustomDes {
        enum class Mode { Encrypt, Decrypt }

        val KEY_1: ByteArray = "!@#)(*$%".toByteArray(Charsets.US_ASCII)
        val KEY_2: ByteArray = "123ZXC!@".toByteArray(Charsets.US_ASCII)
        val KEY_3: ByteArray = "!@#)(NHL".toByteArray(Charsets.US_ASCII)

        private val SBOX1 = intArrayOf(
            14,4,13,1,2,15,11,8,3,10,6,12,5,9,0,7,
            0,15,7,4,14,2,13,1,10,6,12,11,9,5,3,8,
            4,1,14,8,13,6,2,11,15,12,9,7,3,10,5,0,
            15,12,8,2,4,9,1,7,5,11,3,14,10,0,6,13
        )
        private val SBOX2 = intArrayOf(
            15,1,8,14,6,11,3,4,9,7,2,13,12,0,5,10,
            3,13,4,7,15,2,8,15,12,0,1,10,6,9,11,5,
            0,14,7,11,10,4,13,1,5,8,12,6,9,3,2,15,
            13,8,10,1,3,15,4,2,11,6,7,12,0,5,14,9
        )
        private val SBOX3 = intArrayOf(
            10,0,9,14,6,3,15,5,1,13,12,7,11,4,2,8,
            13,7,0,9,3,4,6,10,2,8,5,14,12,11,15,1,
            13,6,4,9,8,15,3,0,11,1,2,12,5,10,14,7,
            1,10,13,0,6,9,8,7,4,15,14,3,11,5,2,12
        )
        private val SBOX4 = intArrayOf(
            7,13,14,3,0,6,9,10,1,2,8,5,11,12,4,15,
            13,8,11,5,6,15,0,3,4,7,2,12,1,10,14,9,
            10,6,9,0,12,11,7,13,15,1,3,14,5,2,8,4,
            3,15,0,6,10,10,13,8,9,4,5,11,12,7,2,14
        )
        private val SBOX5 = intArrayOf(
            2,12,4,1,7,10,11,6,8,5,3,15,13,0,14,9,
            14,11,2,12,4,7,13,1,5,0,15,10,3,9,8,6,
            4,2,1,11,10,13,7,8,15,9,12,5,6,3,0,14,
            11,8,12,7,1,14,2,13,6,15,0,9,10,4,5,3
        )
        private val SBOX6 = intArrayOf(
            12,1,10,15,9,2,6,8,0,13,3,4,14,7,5,11,
            10,15,4,2,7,12,9,5,6,1,13,14,0,11,3,8,
            9,14,15,5,2,8,12,3,7,0,4,10,1,13,11,6,
            4,3,2,12,9,5,15,10,11,14,1,7,6,0,8,13
        )
        private val SBOX7 = intArrayOf(
            4,11,2,14,15,0,8,13,3,12,9,7,5,10,6,1,
            13,0,11,7,4,9,1,10,14,3,5,12,2,15,8,6,
            1,4,11,13,12,3,7,14,10,15,6,8,0,5,9,2,
            6,11,13,8,1,4,10,7,9,5,0,15,14,2,3,12
        )
        private val SBOX8 = intArrayOf(
            13,2,8,4,6,15,11,1,10,9,3,14,5,0,12,7,
            1,15,13,8,10,3,7,4,12,5,6,11,0,14,9,2,
            7,11,4,1,9,12,14,2,0,6,10,13,15,3,5,8,
            2,1,14,7,4,10,8,13,15,12,9,0,3,5,6,11
        )

        private val S_BOXES = arrayOf(SBOX1, SBOX2, SBOX3, SBOX4, SBOX5, SBOX6, SBOX7, SBOX8)

        private val P_BOX = intArrayOf(
            16,7,20,21,29,12,28,17,
            1,15,23,26,5,18,31,10,
            2,8,24,14,32,27,3,9,
            19,13,30,6,22,11,4,25
        )

        private val E_BOX_TABLE = intArrayOf(
            32,1,2,3,4,5,
            4,5,6,7,8,9,
            8,9,10,11,12,13,
            12,13,14,15,16,17,
            16,17,18,19,20,21,
            20,21,22,23,24,25,
            24,25,26,27,28,29,
            28,29,30,31,32,1
        )

        private val SP_TABLES: Array<IntArray> by lazy { generateSpTables() }
        private val TABLES: DesPermutationTables by lazy { DesPermutationTables() }

        fun keySchedule(key: ByteArray, mode: Mode): Array<ByteArray> {
            val keyRndShift = intArrayOf(1, 1, 2, 2, 2, 2, 2, 2, 1, 2, 2, 2, 2, 2, 2, 1)
            val keyPermC = intArrayOf(
                56, 48, 40, 32, 24, 16, 8,
                0, 57, 49, 41, 33, 25, 17,
                9, 1, 58, 50, 42, 34, 26,
                18, 10, 2, 59, 51, 43, 35
            )
            val keyPermD = intArrayOf(
                62, 54, 46, 38, 30, 22, 14,
                6, 61, 53, 45, 37, 29, 21,
                13, 5, 60, 52, 44, 36, 28,
                20, 12, 4, 27, 19, 11, 3
            )
            val keyCompression = intArrayOf(
                13, 16, 10, 23, 0, 4, 2, 27,
                14, 5, 20, 9, 22, 18, 11, 3,
                25, 7, 15, 6, 26, 19, 12, 1,
                40, 51, 30, 36, 46, 54, 29, 39,
                50, 44, 32, 47, 43, 48, 38, 55,
                33, 52, 45, 41, 49, 35, 28, 31
            )

            require(key.size == 8) { "DES key must be 8 bytes" }
            val schedule = Array(ROUNDS) { ByteArray(SUB_KEY_SIZE) }

            val c0 = permuteFromKeyBytes(key, keyPermC)
            val d0 = permuteFromKeyBytes(key, keyPermD)
            var c = (c0.toInt() shl 4)
            var d = (d0.toInt() shl 4)

            keyRndShift.forEachIndexed { i, shift ->
                c = rotateLeft28bitInU32(c, shift)
                d = rotateLeft28bitInU32(d, shift)
                val toGen = if (mode == Mode.Decrypt) 15 - i else i

                var subkey48 = 0L
                keyCompression.forEachIndexed { k, pos ->
                    val bit = if (pos < 28) {
                        (c ushr (31 - pos)) and 1
                    } else {
                        (d ushr (31 - (pos - 27))) and 1
                    }
                    if (bit != 0) {
                        subkey48 = subkey48 or (1L shl (47 - k))
                    }
                }

                val bytes = longToBytesBE(subkey48)
                bytes.copyInto(schedule[toGen], 0, 2, 8)
            }

            return schedule
        }

        fun desCrypt(input: ByteArray, output: ByteArray, key: Array<ByteArray>, outputOffset: Int = 0) {
            val state = IntArray(2)
            initialPermutation(state, input)

            for (roundKey in key.take(15)) {
                val prevRight = state[1]
                val prevLeft = state[0]
                state[1] = prevLeft xor fFunction(prevRight, roundKey)
                state[0] = prevRight
            }

            state[0] = state[0] xor fFunction(state[1], key[15])
            inversePermutation(state, output, outputOffset)
        }

        private fun fFunction(state: Int, key: ByteArray): Int {
            val expanded = applyEBoxPermutation(state)
            val key64 = bytesToLongBE(byteArrayOf(0, 0) + key)
            val xor = expanded xor key64

            /**
             * QQ Music 使用自定义的 S-Box 索引计算（非标准 DES）
             * 索引计算：((a & 0x20) | ((a & 0x1f) >> 1) | ((a & 0x01) << 4))
             */
            fun calculateSBoxIndex(value: Long): Int {
                val a = value.toInt()
                return ((a and 0x20) or ((a and 0x1f) shr 1) or ((a and 0x01) shl 4))
            }

            return SP_TABLES[0][calculateSBoxIndex(xor ushr 42)] or
                SP_TABLES[1][calculateSBoxIndex(xor ushr 36)] or
                SP_TABLES[2][calculateSBoxIndex(xor ushr 30)] or
                SP_TABLES[3][calculateSBoxIndex(xor ushr 24)] or
                SP_TABLES[4][calculateSBoxIndex(xor ushr 18)] or
                SP_TABLES[5][calculateSBoxIndex(xor ushr 12)] or
                SP_TABLES[6][calculateSBoxIndex(xor ushr 6)] or
                SP_TABLES[7][calculateSBoxIndex(xor and 0x3F)]
        }

        private fun initialPermutation(state: IntArray, input: ByteArray) {
            state[0] = 0
            state[1] = 0
            TABLES.ipTable.forEachIndexed { i, tSlice ->
                val lookup = tSlice[input[i].toInt() and 0xFF]
                state[0] = state[0] or lookup.first
                state[1] = state[1] or lookup.second
            }
        }

        private fun inversePermutation(state: IntArray, output: ByteArray, outputOffset: Int) {
            val stateU64 = ((state[0].toLong() and 0xFFFF_FFFFL) shl 32) or
                (state[1].toLong() and 0xFFFF_FFFFL)
            val stateBytes = longToBytesBE(stateU64)
            var result = 0L
            stateBytes.forEachIndexed { i, b ->
                result = result or TABLES.invIpTable[i][b.toInt() and 0xFF]
            }
            longToBytesBE(result).copyInto(output, outputOffset)
        }

        private fun generateSpTables(): Array<IntArray> {
            return Array(8) { sBoxIdx ->
                IntArray(64) { sBoxInput ->
                    val sBoxIndex = calculateSboxIndex(sBoxInput)
                    val fourBitOutput = S_BOXES[sBoxIdx][sBoxIndex]
                    val preP = fourBitOutput shl (28 - (sBoxIdx * 4))
                    applyQqPboxPermutation(preP)
                }
            }
        }

        private fun applyQqPboxPermutation(input: Int): Int {
            val sourceBits = IntArray(32) { i -> (input ushr (31 - i)) and 1 }
            val destBits = IntArray(32) { idx -> sourceBits[P_BOX[idx] - 1] }
            var output = 0
            destBits.forEachIndexed { i, bit ->
                output = output or (bit shl (31 - i))
            }
            return output
        }

        private fun calculateSboxIndex(a: Int): Int {
            return (a and 0x20) or ((a and 0x1F) ushr 1) or ((a and 0x01) shl 4)
        }

        private fun rotateLeft28bitInU32(value: Int, amount: Int): Int {
            val bits28Mask = 0xFFFF_FFF0.toInt()
            return ((value shl amount) or (value ushr (28 - amount))) and bits28Mask
        }

        private fun permuteFromKeyBytes(key: ByteArray, table: IntArray): Long {
            val word1 = u32FromLe(key, 0)
            val word2 = u32FromLe(key, 4)
            val composed = ((word1.toLong() and 0xFFFF_FFFFL) shl 32) or (word2.toLong() and 0xFFFF_FFFFL)
            var output = 0L
            val outputLen = table.size
            table.forEachIndexed { i, pos ->
                val bit = (composed ushr (63 - pos)) and 1L
                if (bit != 0L) {
                    output = output or (1L shl (outputLen - 1 - i))
                }
            }
            return output
        }

        private fun applyEBoxPermutation(input: Int): Long {
            var output = 0L
            E_BOX_TABLE.forEachIndexed { i, sourceBitPos ->
                val shift = 32 - sourceBitPos
                val bit = (input ushr shift) and 1
                output = output or (bit.toLong() shl (47 - i))
            }
            return output
        }

        private class DesPermutationTables {
            val ipTable: Array<Array<Pair<Int, Int>>> = Array(8) { Array(256) { 0 to 0 } }
            val invIpTable: Array<LongArray> = Array(8) { LongArray(256) }

            init {
                val ipRule = intArrayOf(
                    34, 42, 50, 58, 2, 10, 18, 26,
                    36, 44, 52, 60, 4, 12, 20, 28,
                    38, 46, 54, 62, 6, 14, 22, 30,
                    40, 48, 56, 64, 8, 16, 24, 32,
                    33, 41, 49, 57, 1, 9, 17, 25,
                    35, 43, 51, 59, 3, 11, 19, 27,
                    37, 45, 53, 61, 5, 13, 21, 29,
                    39, 47, 55, 63, 7, 15, 23, 31
                )
                val invIpRule = intArrayOf(
                    37, 5, 45, 13, 53, 21, 61, 29,
                    38, 6, 46, 14, 54, 22, 62, 30,
                    39, 7, 47, 15, 55, 23, 63, 31,
                    40, 8, 48, 16, 56, 24, 64, 32,
                    33, 1, 41, 9, 49, 17, 57, 25,
                    34, 2, 42, 10, 50, 18, 58, 26,
                    35, 3, 43, 11, 51, 19, 59, 27,
                    36, 4, 44, 12, 52, 20, 60, 28
                )

                val input = ByteArray(8)
                for (bytePos in 0 until 8) {
                    for (byteVal in 0 until 256) {
                        input.fill(0)
                        input[bytePos] = byteVal.toByte()
                        val permuted = applyPermutation(input, ipRule)
                        val hi = (permuted ushr 32).toInt()
                        val lo = permuted.toInt()
                        ipTable[bytePos][byteVal] = hi to lo
                    }
                }

                for (blockPos in 0 until 8) {
                    for (blockVal in 0 until 256) {
                        val tempInput = (blockVal.toLong() shl (56 - (blockPos * 8)))
                        val permuted = applyPermutation(longToBytesBE(tempInput), invIpRule)
                        invIpTable[blockPos][blockVal] = permuted
                    }
                }
            }

            private fun applyPermutation(input: ByteArray, rule: IntArray): Long {
                val normalized = bytesToLongBE(input)
                var result = 0L
                rule.forEachIndexed { i, srcBitPosFrom1 ->
                    val srcBitPos = srcBitPosFrom1 - 1
                    val bit = (normalized ushr (63 - srcBitPos)) and 1L
                    result = result or (bit shl (63 - i))
                }
                return result
            }
        }

        private fun u32FromLe(bytes: ByteArray, offset: Int): Int {
            return (bytes[offset].toInt() and 0xFF) or
                ((bytes[offset + 1].toInt() and 0xFF) shl 8) or
                ((bytes[offset + 2].toInt() and 0xFF) shl 16) or
                ((bytes[offset + 3].toInt() and 0xFF) shl 24)
        }

        private fun bytesToLongBE(bytes: ByteArray): Long {
            var value = 0L
            for (b in bytes) {
                value = (value shl 8) or (b.toLong() and 0xFF)
            }
            return value
        }

        private fun longToBytesBE(value: Long): ByteArray {
            val out = ByteArray(8)
            for (i in 0 until 8) {
                out[7 - i] = ((value ushr (8 * i)) and 0xFF).toByte()
            }
            return out
        }
    }

    fun looksLikeHex(text: String): Boolean {
        val normalized = text.trim().lowercase(Locale.ROOT)
        return normalized.isNotEmpty() && normalized.length % 2 == 0 && normalized.all { it in '0'..'9' || it in 'a'..'f' }
    }
}

package io.github.zeehan2005.scoremuse.data.parser

import io.github.zeehan2005.scoremuse.data.parser.global.processSyllableText
import io.github.zeehan2005.scoremuse.global.LyricLine
import io.github.zeehan2005.scoremuse.global.LyricWord
import timber.log.Timber

/**
 * QQ 音乐 QRC 格式解析器（逐字歌词格式）
 * 
 * QRC 是 QQ 音乐的专有歌词格式，支持逐字精确时间戳。
 * 
 * 格式特点：
 * - 行级时间戳：[起始时间，持续时间]（单位：毫秒）
 * - 逐字时间戳：文本 (起始时间，持续时间)
 * - 可能包含 XML 包装（需要从 XML 属性中提取）
 * 
 * 示例：
 * [0,5000] 你 (0,500) 好 (500,500) 世 (1000,500) 界 (1500,500)
 * 表示：整行从 0ms 开始持续 5000ms，其中"你"从 0ms 开始持续 500ms，依此类推
 */
object QrcParser {

    /**
     * 正则表达式：匹配 QRC 逐字令牌
     * 分组：text=歌词文本，start=开始时间，duration=持续时间
     * 例如："你好 (0,500)" -> text="你好", start=0, duration=500
     */
    private val lyricTokenRegex = Regex("""(?<text>.*?)\((?<start>\d+),(?<duration>\d+)\)""")

    /**
     * 正则表达式：匹配 QRC 行级时间戳
     * 格式：[起始时间，持续时间]
     */
    private val qrcLineTimestampRegex = Regex("""^\[(\d+),(\d+)]""")

    /**
     * 解析 QRC 格式内容
     * 
     * 解析流程：
     * 1. 如果内容是 XML 格式，先提取 LyricContent 属性值
     * 2. 逐行解析，识别行级时间戳和逐字时间戳
     * 3. 构建 LyricLine 对象列表
     * 
     * @param content QRC 格式的完整歌词文本（可能是 XML 包装的）
     * @return 解析后的 LyricLine 列表
     */
    fun parse(content: String): List<LyricLine> {
        /** 如果是 XML 格式，需要先提取歌词内容 */
        val rawContent = extractQrcFromXmlIfNeeded(content)

        // 调试日志：输出原始内容的基本信息
        Timber.d("[QrcParser] Raw content length=${rawContent.length}, lineCount=${rawContent.lines().size}, containsNewline=${rawContent.contains('\n')}")
        rawContent.lines().take(10).forEachIndexed { index, line ->
            Timber.d("[QrcParser] Raw line $index: ${line.take(200)}")
        }

        val finalLines = mutableListOf<LyricLine>()
        mutableMapOf<String, MutableList<String>>()

        // 逐行解析
        for (raw in rawContent.lines()) {
            val line = raw.trim()
            if (line.isEmpty()) continue
            // 使用统一的元数据检测函数
            // TEMPORARILY DISABLED: MetadataStripper.isMetadataLine(line)
            // if (MetadataStripper.isMetadataLine(line)) continue

            // 解析单行并添加到结果列表
            parseSingleLine(line)?.let { finalLines.add(it) }
        }

        /** 调试输出：统计解析结果 */
        val totalWords = finalLines.sumOf { it.words.size }
        Timber.d("[QrcParser] Output: ${finalLines.size} lines, $totalWords words (avg=${if (finalLines.isNotEmpty()) totalWords.toDouble() / finalLines.size else 0.0})")

        return finalLines
    }

    /**
     * 解析单个 QRC 行
     * 
     * QRC 行格式：[起始时间，持续时间] 文本 (起始时间，持续时间) 文本 (起始时间，持续时间)...
     * 
     * 处理逻辑：
     * 1. 提取行级时间戳（如果有）
     * 2. 逐个提取逐字令牌（文本 + 时间戳）
     * 3. 如果没有逐字时间戳但有行级时间戳，使用 fallback 模式
     * 4. 构建 LyricLine 对象
     * 
     * @param line 单行 QRC 歌词文本
     * @return 解析后的 LyricLine，如果无法解析则返回 null
     */
    private fun parseSingleLine(line: String): LyricLine? {
        /** QRC 行头部：[lineStart,lineDuration] (单位：毫秒) */
        val lineStartMs = qrcLineTimestampRegex.find(line)?.groups?.get(1)?.value?.toLongOrNull()
        val lineDurationMs = qrcLineTimestampRegex.find(line)?.groups?.get(2)?.value?.toLongOrNull()

        /** 移除行级时间戳，剩下的就是歌词内容 */
        val lineContent = qrcLineTimestampRegex.replace(line, "")
        val words = mutableListOf<LyricWord>()

        // 逐个匹配逐字令牌
        for (capture in lyricTokenRegex.findAll(lineContent)) {
            val rawText = capture.groups["text"]?.value.orEmpty()
            val processed = processSyllableText(rawText, words) ?: continue
            val (cleanText, endsWithSpace) = processed

            val startMs = capture.groups["start"]?.value?.toLongOrNull() ?: continue
            val durationMs = capture.groups["duration"]?.value?.toLongOrNull() ?: continue

            /** 根据是否有尾随空格决定是否在单词后添加空格 */
            val text = if (endsWithSpace) "$cleanText " else cleanText
            words.add(
                LyricWord(
                    word = text,
                    startTime = startMs,
                    endTime = startMs + maxOf(1L, durationMs) // 确保持续时间至少为 1ms，防止 JS 侧计算 NaN
                )
            )
        }

        // Fallback 模式：处理只有行级时间戳而没有逐字时间戳的情况
        // Some QRC lines include only a line-level timestamp ([start,duration]) without per-word timings.
        // In that case, we still want to emit a lyric line rather than drop it.
        // However, some files may include placeholder tokens like "(240410,1651)" where there is no actual lyric text.
        // Do not treat these timestamp tokens as lyric text.
        if (words.isEmpty() && lineStartMs != null) {
            val fallbackText = lineContent.trim()
            /**
             * Normalize to catch hidden/zero-width characters or other noise that still renders as
             * a timestamp-like token (e.g. "\u200B(240410,1651)").
             */
            val normalized = fallbackText.replace(Regex("[^\\d(),]"), "")
            val isTimestampToken = Regex("^\\(\\d+,\\d+\\)(?:\\(\\d+,\\d+\\))*$").matches(normalized)

            // 如果不是纯时间戳占位符，就作为整行歌词处理
            if (fallbackText.isNotEmpty() && !isTimestampToken) {
                val lineEnd = lineStartMs + (lineDurationMs ?: 0)
                words.add(
                    LyricWord(
                        word = fallbackText,
                        startTime = lineStartMs,
                        endTime = maxOf(lineStartMs + 1, lineEnd) // 确保持续时间至少为 1ms
                    )
                )
            }
        }

        // 如果没有解析出任何单词，返回 null（丢弃这一行）
        if (words.isEmpty()) return null

        /**
         * 计算行的开始和结束时间
         * 优先使用行级时间戳，如果没有则使用第一个和最后一个单词的时间
         */
        val lineStart = lineStartMs ?: words.first().startTime
        val rawLineEnd = lineStart + (lineDurationMs ?: (words.last().endTime - lineStart))
        val lineEnd = maxOf(lineStart + 1, rawLineEnd) // 确保行持续时间至少为 1ms

        // 创建 LyricLine 对象
        return LyricLine(
            startTime = lineStart,
            endTime = lineEnd,
            text = words.joinToString(separator = "") { it.word }.trimEnd(),  // 拼接所有单词
            words = words
        )
    }

    /**
     * 从 XML 包装中提取 QRC 歌词内容
     * 
     * QQ 音乐的 QRC 输出有时会被包装在 XML 标签中，例如：
     * <Lyric_1 LyricContent="歌词内容..." />
     * 
     * 由于 XML 解析器会规范化空白字符（换行符变成空格），
     * 我们使用正则表达式直接提取属性值，保留原始换行符。
     * 
     * @param content 可能包含 XML 包装的 QRC 内容
     * @return 提取后的纯 QRC 歌词文本
     */
    private fun extractQrcFromXmlIfNeeded(content: String): String {
        // 如果不包含 XML 特征标记，直接返回原始内容
        if (!content.contains("<QrcInfos", ignoreCase = true) &&
            !content.contains("<LyricInfo", ignoreCase = true) &&
            !Regex("""<Lyric_\d+\b""", RegexOption.IGNORE_CASE).containsMatchIn(content)
        ) {
            return content
        }

        // QQ QRC output uses LyricContent="..." attributes, and XML parsers normalize whitespace
        // (newlines become spaces), which breaks line splitting. We prefer regex extraction to
        // preserve original newlines.
        //
        // Note: QRC payloads often wrap LyricContent in double quotes, but the lyric text may
        // contain apostrophes or even internal quotation marks. We want to use the outermost
        // quotes for the attribute value so that inner quotes don't truncate the match.
        val extracted = mutableListOf<String>()
        /** 匹配 <Lyric_N LyricContent='...' /> 或 <Lyric_N LyricContent="..." /> */
        val tagStartRegex = Regex("""<Lyric_\d+\b[^>]*\bLyricContent=(['"])""", RegexOption.IGNORE_CASE)
        var searchIndex = 0

        // 循环查找所有 LyricContent 属性
        while (true) {
            val match = tagStartRegex.find(content, startIndex = searchIndex) ?: break
            val quoteChar = match.groupValues[1].single()  // 获取引号类型（单引号或双引号）
            val valueStart = match.range.last + 1  // 属性值开始位置

            /** Find the end of the current tag so we can pick the outermost closing quote inside it. */
            val tagEnd = content.indexOf('>', startIndex = valueStart).takeIf { it >= 0 } ?: content.length
            val lastQuoteBeforeTagEnd = content.lastIndexOf(quoteChar, startIndex = tagEnd - 1)
            val valueEnd = if (lastQuoteBeforeTagEnd >= valueStart) {
                lastQuoteBeforeTagEnd
            } else {
                // Fallback: find the first quote after the start
                content.indexOf(quoteChar, startIndex = valueStart).takeIf { it >= 0 } ?: content.length
            }

            /** 提取属性值并进行 XML 反转义 */
            val rawValue = content.substring(valueStart, valueEnd)
            extracted.add(unescapeXmlAttribute(rawValue))

            searchIndex = valueEnd + 1
        }

        // 如果成功提取了内容，用换行符拼接并返回
        if (extracted.isNotEmpty()) {
            Timber.d("[QrcParser] Extracted $extracted.size LyricContent entries from QRC XML (regex): ${extracted.joinToString("\\n").take(500)}")
            return extracted.joinToString(separator = "\n")
        }

        // Fallback to DOM parsing if regex failed (very rare)
        // 如果正则表达式失败（极罕见），使用 DOM 解析器
        return try {
            val builder = javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder()
            val doc = builder.parse(content.byteInputStream())
            val lyricContents = mutableListOf<String>()

            val allElements = doc.getElementsByTagName("*")
            for (i in 0 until allElements.length) {
                val node = allElements.item(i)
                if (node is org.w3c.dom.Element) {
                    val lyricContent = node.getAttribute("LyricContent")
                    if (!lyricContent.isNullOrBlank()) {
                        lyricContents.add(lyricContent)
                    }
                }
            }

            if (lyricContents.isEmpty()) {
                Timber.d("[QrcParser] Detected QRC XML but no LyricContent attributes found; falling back to raw content")
                return content
            }

            Timber.d("[QrcParser] Extracted $lyricContents.size LyricContent entries from QRC XML (DOM)")
            lyricContents.joinToString(separator = "\n")
        } catch (e: Exception) {
            Timber.w("[QrcParser] Failed to parse QRC XML content; falling back to raw content $e")
            content
        }
    }

    /**
     * XML 属性反转移函数
     * 
     * 将 XML 实体引用转换回原始字符：
     * - &quot; -> "
     * - &apos; -> '
     * - &lt; -> <
     * - &gt; -> >
     * - &amp; -> &
     * - &#数字; -> Unicode 字符（十进制）
     * - &#x 十六进制; -> Unicode 字符（十六进制）
     * 
     * @param value 包含 XML 实体的字符串
     * @return 反转义后的字符串
     */
    private fun unescapeXmlAttribute(value: String): String {
        return value
            .replace("&quot;", "\"")      // 双引号
            .replace("&apos;", "'")       // 单引号
            .replace("&lt;", "<")         // 小于号
            .replace("&gt;", ">")         // 大于号
            .replace("&amp;", "&")        // 和号（必须最后处理）
            .replace(Regex("&#(\\d+);")) { match ->
                // 十进制 Unicode 字符引用
                match.groups[1]?.value?.toIntOrNull()?.toChar()?.toString() ?: match.value
            }
            .replace(Regex("&#x([0-9A-Fa-f]+);")) { match ->
                // 十六进制 Unicode 字符引用
                match.groups[1]?.value?.toIntOrNull(16)?.toChar()?.toString() ?: match.value
            }
    }
}

