    val httpClient = HttpClient(CIO) {
        engine {
            requestTimeout = 30_000
        }
    }

    try {
        // ═══════════════════════════════════════════════════════
        // 步骤 1: 搜索歌曲
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📡 【步骤 1】搜索歌曲")
