// ============================================================
// 3DES 解密（QQ Music 非标准实现）
// ============================================================

private const val ROUNDS = 16
private const val SUB_KEY_SIZE = 6
private const val DES_BLOCK_SIZE = 8

/**
 * 3DES-EDE 解密
 *
 * QQ Music 使用非标准 DES 实现:
 * - 自定义 IP 表（初始置换）
 * - 自定义 S-BOX 索引算法
 * - 3DES-EDE 模式 (K3-Decrypt → K2-Encrypt → K1-Decrypt)
 */
fun decrypt3DesEde(encryptedBytes: ByteArray): ByteArray {
    require(encryptedBytes.size % DES_BLOCK_SIZE == 0) {
        "数据长度 ${encryptedBytes.size} 不是 ${DES_BLOCK_SIZE} 的倍数"
    }

    println("   逐块 3DES 解密...")
    val decryptSchedule = arrayOf(
        QqDes.keySchedule(QqDes.KEY_3, QqDes.Mode.Decrypt),
        QqDes.keySchedule(QqDes.KEY_2, QqDes.Mode.Encrypt),
        QqDes.keySchedule(QqDes.KEY_1, QqDes.Mode.Decrypt)
    )

    val result = ByteArray(encryptedBytes.size)
    val blockCount = encryptedBytes.size / DES_BLOCK_SIZE

    for (blockIdx in 0 until blockCount) {
        val offset = blockIdx * DES_BLOCK_SIZE
        val temp1 = ByteArray(DES_BLOCK_SIZE)
        val temp2 = ByteArray(DES_BLOCK_SIZE)
        val block = encryptedBytes.copyOfRange(offset, offset + DES_BLOCK_SIZE)

        // K3 解密
        QqDes.desCrypt(block, temp1, decryptSchedule[0])
        // K2 加密
        QqDes.desCrypt(temp1, temp2, decryptSchedule[1])
        // K1 解密
        QqDes.desCrypt(temp2, result, decryptSchedule[2], offset)

        // 对前 3 个块输出调试信息
        if (blockIdx < 3) {
            println("     块 ${blockIdx + 1}/$blockCount (偏移 $offset):")
            println("       输入:      ${block.joinToString(" ") { "%02X".format(it) }}")
            println("       中间 K3-D: ${temp1.joinToString(" ") { "%02X".format(it) }}")
            println("       中间 K2-E: ${temp2.joinToString(" ") { "%02X".format(it) }}")
            println("       输出 K1-D: ${result.copyOfRange(offset, offset + 8).joinToString(" ") { "%02X".format(it) }}")
        }
    }

    return result
}

