        3, 13, 4, 7, 15, 2, 8, 15, 12, 0, 1, 10, 6, 9, 11, 5,
        0, 14, 7, 11, 10, 4, 13, 1, 5, 8, 12, 6, 9, 3, 2, 15,
        13, 8, 10, 1, 3, 15, 4, 2, 11, 6, 7, 12, 0, 5, 14, 9
    )
    private val SBOX3 = intArrayOf(
        10, 0, 9, 14, 6, 3, 15, 5, 1, 13, 12, 7, 11, 4, 2, 8,
        13, 7, 0, 9, 3, 4, 6, 10, 2, 8, 5, 14, 12, 11, 15, 1,
        13, 6, 4, 9, 8, 15, 3, 0, 11, 1, 2, 12, 5, 10, 14, 7,
        1, 10, 13, 0, 6, 9, 8, 7, 4, 15, 14, 3, 11, 5, 2, 12
    )
    private val SBOX4 = intArrayOf(
        7, 13, 14, 3, 0, 6, 9, 10, 1, 2, 8, 5, 11, 12, 4, 15,
        13, 8, 11, 5, 6, 15, 0, 3, 4, 7, 2, 12, 1, 10, 14, 9,
        10, 6, 9, 0, 12, 11, 7, 13, 15, 1, 3, 14, 5, 2, 8, 4,
        3, 15, 0, 6, 10, 10, 13, 8, 9, 4, 5, 11, 12, 7, 2, 14
    )
    private val SBOX5 = intArrayOf(
        2, 12, 4, 1, 7, 10, 11, 6, 8, 5, 3, 15, 13, 0, 14, 9,
        14, 11, 2, 12, 4, 7, 13, 1, 5, 0, 15, 10, 3, 9, 8, 6,
        4, 2, 1, 11, 10, 13, 7, 8, 15, 9, 12, 5, 6, 3, 0, 14,
        11, 8, 12, 7, 1, 14, 2, 13, 6, 15, 0, 9, 10, 4, 5, 3
    )
    private val SBOX6 = intArrayOf(
        12, 1, 10, 15, 9, 2, 6, 8, 0, 13, 3, 4, 14, 7, 5, 11,
        10, 15, 4, 2, 7, 12, 9, 5, 6, 1, 13, 14, 0, 11, 3, 8,
        9, 14, 15, 5, 2, 8, 12, 3, 7, 0, 4, 10, 1, 13, 11, 6,
        4, 3, 2, 12, 9, 5, 15, 10, 11, 14, 1, 7, 6, 0, 8, 13
    )
    private val SBOX7 = intArrayOf(
        4, 11, 2, 14, 15, 0, 8, 13, 3, 12, 9, 7, 5, 10, 6, 1,
        13, 0, 11, 7, 4, 9, 1, 10, 14, 3, 5, 12, 2, 15, 8, 6,
        1, 4, 11, 13, 12, 3, 7, 14, 10, 15, 6, 8, 0, 5, 9, 2,
        6, 11, 13, 8, 1, 4, 10, 7, 9, 5, 0, 15, 14, 2, 3, 12
    )
    private val SBOX8 = intArrayOf(
        13, 2, 8, 4, 6, 15, 11, 1, 10, 9, 3, 14, 5, 0, 12, 7,
        1, 15, 13, 8, 10, 3, 7, 4, 12, 5, 6, 11, 0, 14, 9, 2,
        7, 11, 4, 1, 9, 12, 14, 2, 0, 6, 10, 13, 15, 3, 5, 8,
        2, 1, 14, 7, 4, 10, 8, 13, 15, 12, 9, 0, 3, 5, 6, 11
    )

    private val S_BOXES = arrayOf(SBOX1, SBOX2, SBOX3, SBOX4, SBOX5, SBOX6, SBOX7, SBOX8)

    // P-BOX（置换）
    private val P_BOX = intArrayOf(
        16, 7, 20, 21, 29, 12, 28, 17,
        1, 15, 23, 26, 5, 18, 31, 10,
        2, 8, 24, 14, 32, 27, 3, 9,
        19, 13, 30, 6, 22, 11, 4, 25
    )

    // E-BOX（扩展置换）
    private val E_BOX_TABLE = intArrayOf(
        32, 1, 2, 3, 4, 5,
        4, 5, 6, 7, 8, 9,
        8, 9, 10, 11, 12, 13,
        12, 13, 14, 15, 16, 17,
        16, 17, 18, 19, 20, 21,
        20, 21, 22, 23, 24, 25,
        24, 25, 26, 27, 28, 29,
        28, 29, 30, 31, 32, 1
    )

    // SP 表（预计算）
    private val SP_TABLES: Array<IntArray> by lazy { generateSpTables() }
    private val TABLES: DesPermutationTables by lazy { DesPermutationTables() }

    /**
     * 密钥调度：生成 16 轮子密钥
     */
    fun keySchedule(key: ByteArray, mode: Mode): Array<ByteArray> {
        val keyRndShift = intArrayOf(1, 1, 2, 2, 2, 2, 2, 2, 1, 2, 2, 2, 2, 2, 2, 1)
        val keyPermC = intArrayOf(
            56, 48, 40, 32, 24, 16, 8,
            0, 57, 49, 41, 33, 25, 17,
            9, 1, 58, 50, 42, 34, 26,
            18, 10, 2, 59, 51, 43, 35
        )
        val keyPermD = intArrayOf(
            62, 54, 46, 38, 30, 22, 14,
            6, 61, 53, 45, 37, 29, 21,
            13, 5, 60, 52, 44, 36, 28,
            20, 12, 4, 27, 19, 11, 3
        )
        val keyCompression = intArrayOf(
            13, 16, 10, 23, 0, 4, 2, 27,
            14, 5, 20, 9, 22, 18, 11, 3,
            25, 7, 15, 6, 26, 19, 12, 1,
            40, 51, 30, 36, 46, 54, 29, 39,
            50, 44, 32, 47, 43, 48, 38, 55,
            33, 52, 45, 41, 49, 35, 28, 31
        )

        require(key.size == 8) { "DES 密钥必须是 8 字节" }
        val schedule = Array(ROUNDS) { ByteArray(SUB_KEY_SIZE) }

        val c0 = permuteFromKeyBytes(key, keyPermC)
        val d0 = permuteFromKeyBytes(key, keyPermD)
        var c = (c0.toInt() shl 4)
        var d = (d0.toInt() shl 4)

        keyRndShift.forEachIndexed { i, shift ->
            c = rotateLeft28bitInU32(c, shift)
            d = rotateLeft28bitInU32(d, shift)
            val toGen = if (mode == Mode.Decrypt) 15 - i else i

            var subkey48 = 0L
            keyCompression.forEachIndexed { k, pos ->
                val bit = if (pos < 28) {
                    (c ushr (31 - pos)) and 1
                } else {
                    (d ushr (31 - (pos - 27))) and 1
                }
                if (bit != 0) {
                    subkey48 = subkey48 or (1L shl (47 - k))
                }
            }

            val bytes = longToBytesBE(subkey48)
            bytes.copyInto(schedule[toGen], 0, 2, 8)
        }

        return schedule
    }

    /**
     * DES 加密/解密 一个 8 字节块
     */
    fun desCrypt(input: ByteArray, output: ByteArray, key: Array<ByteArray>, outputOffset: Int = 0) {
        val state = IntArray(2)
        initialPermutation(state, input)

        for (roundKey in key.take(15)) {
            val prevRight = state[1]
            val prevLeft = state[0]
            state[1] = prevLeft xor fFunction(prevRight, roundKey)
            state[0] = prevRight
        }

        state[0] = state[0] xor fFunction(state[1], key[15])
        inversePermutation(state, output, outputOffset)
    }

    // ============================================================
    // DES 内部函数
    // ============================================================

    private fun fFunction(state: Int, key: ByteArray): Int {
        val expanded = applyEBoxPermutation(state)
        val key64 = bytesToLongBE(byteArrayOf(0, 0) + key)
        val xor = expanded xor key64

        // QQ Music 自定义 S-BOX 索引算法
        fun calculateSBoxIndex(value: Long): Int {
            val a = value.toInt()
            return ((a and 0x20) or ((a and 0x1f) shr 1) or ((a and 0x01) shl 4))
        }

        return SP_TABLES[0][calculateSBoxIndex(xor ushr 42)] or
            SP_TABLES[1][calculateSBoxIndex(xor ushr 36)] or
            SP_TABLES[2][calculateSBoxIndex(xor ushr 30)] or
            SP_TABLES[3][calculateSBoxIndex(xor ushr 24)] or
            SP_TABLES[4][calculateSBoxIndex(xor ushr 18)] or
            SP_TABLES[5][calculateSBoxIndex(xor ushr 12)] or
            SP_TABLES[6][calculateSBoxIndex(xor ushr 6)] or
            SP_TABLES[7][calculateSBoxIndex(xor and 0x3F)]
    }

    private fun initialPermutation(state: IntArray, input: ByteArray) {
        state[0] = 0
        state[1] = 0
        TABLES.ipTable.forEachIndexed { i, tSlice ->
            val lookup = tSlice[input[i].toInt() and 0xFF]
            state[0] = state[0] or lookup.first
            state[1] = state[1] or lookup.second
        }
    }

    private fun inversePermutation(state: IntArray, output: ByteArray, outputOffset: Int) {
        val stateU64 = ((state[0].toLong() and 0xFFFF_FFFFL) shl 32) or
            (state[1].toLong() and 0xFFFF_FFFFL)
        val stateBytes = longToBytesBE(stateU64)
        var result = 0L
        stateBytes.forEachIndexed { i, b ->
            result = result or TABLES.invIpTable[i][b.toInt() and 0xFF]
        }
        longToBytesBE(result).copyInto(output, outputOffset)
    }

    private fun generateSpTables(): Array<IntArray> {
        return Array(8) { sBoxIdx ->
            IntArray(64) { sBoxInput ->
                val sBoxIndex = calculateSboxIndex(sBoxInput)
                val fourBitOutput = S_BOXES[sBoxIdx][sBoxIndex]
                val preP = fourBitOutput shl (28 - (sBoxIdx * 4))
                applyQqPboxPermutation(preP)
            }
        }
    }

    private fun applyQqPboxPermutation(input: Int): Int {
        val sourceBits = IntArray(32) { i -> (input ushr (31 - i)) and 1 }
        val destBits = IntArray(32) { idx -> sourceBits[P_BOX[idx] - 1] }
        var output = 0
        destBits.forEachIndexed { i, bit ->
            output = output or (bit shl (31 - i))
        }
        return output
    }

    private fun calculateSboxIndex(a: Int): Int {
        return (a and 0x20) or ((a and 0x1F) ushr 1) or ((a and 0x01) shl 4)
    }

    private fun rotateLeft28bitInU32(value: Int, amount: Int): Int {
        val bits28Mask = 0xFFFF_FFF0.toInt()
        return ((value shl amount) or (value ushr (28 - amount))) and bits28Mask
    }

    private fun permuteFromKeyBytes(key: ByteArray, table: IntArray): Long {
        val word1 = u32FromLe(key, 0)
        val word2 = u32FromLe(key, 4)
        val composed = ((word1.toLong() and 0xFFFF_FFFFL) shl 32) or (word2.toLong() and 0xFFFF_FFFFL)
        var output = 0L
        val outputLen = table.size
        table.forEachIndexed { i, pos ->
            val bit = (composed ushr (63 - pos)) and 1L
            if (bit != 0L) {
                output = output or (1L shl (outputLen - 1 - i))
            }
        }
        return output
    }

    private fun applyEBoxPermutation(input: Int): Long {
        var output = 0L
        E_BOX_TABLE.forEachIndexed { i, sourceBitPos ->
            val shift = 32 - sourceBitPos
            val bit = (input ushr shift) and 1
            output = output or (bit.toLong() shl (47 - i))
        }
        return output
    }

    // ============================================================
    // DES 置换表（预计算）
    // ============================================================

    private class DesPermutationTables {
        val ipTable: Array<Array<Pair<Int, Int>>> = Array(8) { Array(256) { 0 to 0 } }
        val invIpTable: Array<LongArray> = Array(8) { LongArray(256) }

        init {
            // QQ Music 自定义 IP 表（与标准 DES 不同）
            val ipRule = intArrayOf(
                34, 42, 50, 58, 2, 10, 18, 26,
                36, 44, 52, 60, 4, 12, 20, 28,
                38, 46, 54, 62, 6, 14, 22, 30,
                40, 48, 56, 64, 8, 16, 24, 32,
                33, 41, 49, 57, 1, 9, 17, 25,
                35, 43, 51, 59, 3, 11, 19, 27,
                37, 45, 53, 61, 5, 13, 21, 29,
                39, 47, 55, 63, 7, 15, 23, 31
            )
            val invIpRule = intArrayOf(
                37, 5, 45, 13, 53, 21, 61, 29,
                38, 6, 46, 14, 54, 22, 62, 30,
                39, 7, 47, 15, 55, 23, 63, 31,
                40, 8, 48, 16, 56, 24, 64, 32,
                33, 1, 41, 9, 49, 17, 57, 25,
                34, 2, 42, 10, 50, 18, 58, 26,
                35, 3, 43, 11, 51, 19, 59, 27,
                36, 4, 44, 12, 52, 20, 60, 28
            )

            val input = ByteArray(8)
            for (bytePos in 0 until 8) {
                for (byteVal in 0 until 256) {
                    input.fill(0)
                    input[bytePos] = byteVal.toByte()
                    val permuted = applyPermutation(input, ipRule)
                    val hi = (permuted ushr 32).toInt()
                    val lo = permuted.toInt()
                    ipTable[bytePos][byteVal] = hi to lo
                }
            }

            for (blockPos in 0 until 8) {
                for (blockVal in 0 until 256) {
                    val tempInput = (blockVal.toLong() shl (56 - (blockPos * 8)))
                    val permuted = applyPermutation(longToBytesBE(tempInput), invIpRule)
                    invIpTable[blockPos][blockVal] = permuted
                }
            }
        }

        private fun applyPermutation(input: ByteArray, rule: IntArray): Long {
            val normalized = bytesToLongBE(input)
            var result = 0L
            rule.forEachIndexed { i, srcBitPosFrom1 ->
                val srcBitPos = srcBitPosFrom1 - 1
                val bit = (normalized ushr (63 - srcBitPos)) and 1L
                result = result or (bit shl (63 - i))
            }
            return result
        }
    }

    // ============================================================
    // 工具函数
    // ============================================================

    private fun u32FromLe(bytes: ByteArray, offset: Int): Int {
        return (bytes[offset].toInt() and 0xFF) or
            ((bytes[offset + 1].toInt() and 0xFF) shl 8) or
            ((bytes[offset + 2].toInt() and 0xFF) shl 16) or
            ((bytes[offset + 3].toInt() and 0xFF) shl 24)
    }

    private fun bytesToLongBE(bytes: ByteArray): Long {
        var value = 0L
        for (b in bytes) {
            value = (value shl 8) or (b.toLong() and 0xFF)
        }
        return value
    }

    private fun longToBytesBE(value: Long): ByteArray {
        val out = ByteArray(8)
        for (i in 0 until 8) {
            out[7 - i] = ((value ushr (8 * i)) and 0xFF).toByte()
        }
        return out
    }
}

// ============================================================
// Zlib 解压
// ============================================================

/**
 * 尝试多种 zlib 解压策略
 */
fun tryZlibDecompress(data: ByteArray): ByteArray {
    // 策略 1: 标准 zlib 解压（带 zlib 头）
    if (data.isNotEmpty() && (data[0].toInt() and 0xFF) == 0x78) {
        try {
            val result = InflaterInputStream(ByteArrayInputStream(data)).use { it.readBytes() }
            println("   ✅ 策略 1 (标准 zlib) 成功: ${result.size} 字节")
            return result
        } catch (e: Exception) {
            println("   ❌ 策略 1 (标准 zlib) 失败: $e")
        }
    }

    // 策略 2: 原始 Deflate（无 zlib 头）
    try {
        val inflater = Inflater(true)
        val result = try {
            InflaterInputStream(ByteArrayInputStream(data), inflater).use { it.readBytes() }
        } finally {
            inflater.end()
        }
        println("   ✅ 策略 2 (raw deflate) 成功: ${result.size} 字节")
        return result
    } catch (e: Exception) {
        println("   ❌ 策略 2 (raw deflate) 失败: $e")
    }

    // 策略 3: 寻找 zlib 头偏移
    val candidateOffsets = data.withIndex()
        .filter { it.value.toInt() and 0xFF == 0x78 }
        .map { it.index }
    if (candidateOffsets.isNotEmpty()) {
        println("   尝试策略 3: 从偏移 ${candidateOffsets.joinToString()} 开始解压...")
        for (offset in candidateOffsets) {
            if (offset + 1 >= data.size) continue
            val second = data[offset + 1].toInt() and 0xFF
            val combined = (0x78 shl 8) or second
            if (combined % 31 == 0) {
                try {
                    val result = InflaterInputStream(
                        ByteArrayInputStream(data.copyOfRange(offset, data.size))
                    ).use { it.readBytes() }
                    println("   ✅ 策略 3 (偏移 $offset) 成功: ${result.size} 字节")
                    return result
                } catch (e: Exception) {
                    println("   ❌ 策略 3 (偏移 $offset) 失败: $e")
                }
            }
        }
    }

    throw RuntimeException("所有解压策略均失败")
}

// ============================================================
// QRC 解析器
// ============================================================

data class LyricWord(
    val word: String,
    val startTime: Long,
    val endTime: Long
)

data class LyricLine(
    val startTime: Long,
    val endTime: Long,
    val text: String,
    val words: List<LyricWord>
)

/**
 * 解析 QRC 格式文本
 *
 * QRC 格式:
 *   [行起始时间,行持续时间] 单词1(起始时间,持续时间) 单词2(起始时间,持续时间) ...
 *
 * 示例:
 *   [0,5000] 你 (0,500) 好 (500,500) 世 (1000,500) 界 (1500,500)
 */
fun parseQrc(content: String): List<LyricLine> {
    val lyricTokenRegex = Regex("""(?<text>.*?)\((?<start>\d+),(?<duration>\d+)\)""")
    val lineTimestampRegex = Regex("""^\[(\d+),(\d+)]""")

    val lines = mutableListOf<LyricLine>()

    for (rawLine in content.lines()) {
        val line = rawLine.trim()
        if (line.isEmpty()) continue

        // 匹配行级时间戳
        val lineStartMs = lineTimestampRegex.find(line)
            ?.groups?.get(1)?.value?.toLongOrNull()
        val lineDurationMs = lineTimestampRegex.find(line)
            ?.groups?.get(2)?.value?.toLongOrNull()

        // 移除行级时间戳
        val lineContent = lineTimestampRegex.replace(line, "")
        val words = mutableListOf<LyricWord>()

        // 逐字匹配
        for (capture in lyricTokenRegex.findAll(lineContent)) {
            val text = capture.groups["text"]?.value.orEmpty()
            val startMs = capture.groups["start"]?.value?.toLongOrNull() ?: continue
            val durationMs = capture.groups["duration"]?.value?.toLongOrNull() ?: continue

            val textClean = text.trimEnd()
            words.add(
                LyricWord(
                    word = textClean,
                    startTime = startMs,
                    endTime = startMs + maxOf(1L, durationMs)
                )
            )
        }

        // 如果没有逐字时间戳，但有行级时间戳，作为整行处理
        if (words.isEmpty() && lineStartMs != null) {
            val fallbackText = lineContent.trim()
            val normalized = fallbackText.replace(Regex("[^\\d(),]"), "")
            val isTimestampToken = Regex("^\\(\\d+,\\d+\\)(?:\\(\\d+,\\d+\\))*$").matches(normalized)

            if (fallbackText.isNotEmpty() && !isTimestampToken) {
                val lineEnd = lineStartMs + (lineDurationMs ?: 0)
                words.add(
                    LyricWord(
                        word = fallbackText,
                        startTime = lineStartMs,
                        endTime = maxOf(lineStartMs + 1, lineEnd)
                    )
                )
            }
        }

        if (words.isEmpty()) continue

        val lineStart = lineStartMs ?: words.first().startTime
        val rawLineEnd = lineStart + (lineDurationMs ?: (words.last().endTime - lineStart))
        val lineEnd = maxOf(lineStart + 1, rawLineEnd)

        lines.add(
            LyricLine(
                startTime = lineStart,
                endTime = lineEnd,
                text = words.joinToString(separator = "") { it.word }.trimEnd(),
                words = words
            )
        )
    }

    return lines
}

/**
 * 从 XML 包装中提取 QRC 内容
 */
fun extractQrcFromXmlIfNeeded(content: String): String {
    if (!content.contains("<QrcInfos", ignoreCase = true) &&
        !content.contains("<LyricInfo", ignoreCase = true) &&
        !Regex("""<Lyric_\d+\b""", RegexOption.IGNORE_CASE).containsMatchIn(content)
    ) {
        return content
    }

    println("   ℹ️ 检测到 XML 包装，提取 LyricContent 属性...")

    val extracted = mutableListOf<String>()
    val tagStartRegex = Regex("""<Lyric_\d+\b[^>]*\bLyricContent=(['"])""", RegexOption.IGNORE_CASE)
    var searchIndex = 0

    while (true) {
        val match = tagStartRegex.find(content, startIndex = searchIndex) ?: break
        val quoteChar = match.groupValues[1].single()
        val valueStart = match.range.last + 1
        val tagEnd = content.indexOf('>', startIndex = valueStart).takeIf { it >= 0 } ?: content.length
        val lastQuoteBeforeTagEnd = content.lastIndexOf(quoteChar, startIndex = tagEnd - 1)
        val valueEnd = if (lastQuoteBeforeTagEnd >= valueStart) lastQuoteBeforeTagEnd
        else content.indexOf(quoteChar, startIndex = valueStart).takeIf { it >= 0 } ?: content.length

        val rawValue = content.substring(valueStart, valueEnd)
        extracted.add(unescapeXml(rawValue))
        searchIndex = valueEnd + 1
    }

    if (extracted.isNotEmpty()) {
        return extracted.joinToString(separator = "\n")
    }

    return content
}

fun unescapeXml(value: String): String {
    return value
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
        .replace(Regex("&#(\\d+);")) { match ->
            match.groups[1]?.value?.toIntOrNull()?.toChar()?.toString() ?: match.value
        }
        .replace(Regex("&#x([0-9A-Fa-f]+);")) { match ->
            match.groups[1]?.value?.toIntOrNull(16)?.toChar()?.toString() ?: match.value
        }
}

// ============================================================
// 工具函数
// ============================================================

data class SearchResult(
    val songMid: String,
    val title: String,
    val artist: String,
    val duration: Long
)

fun parseQqSongIds(songId: String): Pair<String?, Long?> {
    val parts = songId.split("::", limit = 2)
    val mid = parts.getOrNull(0)?.takeIf { it.isNotBlank() }
    val numeric = parts.getOrNull(1)?.toLongOrNull()
    if (numeric != null) return mid to numeric
    return if (songId.all { it.isDigit() }) null to songId.toLongOrNull() else songId to null
}

fun looksLikeHex(text: String): Boolean {
    val normalized = text.trim()
    return normalized.isNotEmpty() &&
        normalized.length % 2 == 0 &&
        normalized.all { it in '0'..'9' || it in 'a'..'f' || it in 'A'..'F' }
}

fun decodeHex(value: String): ByteArray {
    val clean = value.trim()
    require(clean.length % 2 == 0) { "无效的 Hex 字符串长度: ${clean.length}" }
    val out = ByteArray(clean.length / 2)
    var i = 0
    while (i < clean.length) {
        val hi = clean[i].digitToIntOrNull(16) ?: error("无效 Hex 字符: ${clean[i]}")
        val lo = clean[i + 1].digitToIntOrNull(16) ?: error("无效 Hex 字符: ${clean[i + 1]}")
        out[i / 2] = ((hi shl 4) or lo).toByte()
        i += 2
    }
    return out
}

/**
 * 检查字节数组是否大部分是可打印 ASCII
 */
fun printIfMostlyAscii(bytes: ByteArray) {
    val printable = bytes.count { b ->
        val c = b.toInt() and 0xFF
        (c in 0x20..0x7E) || c == 0x0A || c == 0x0D || c == 0x09
    }
    val ratio = if (bytes.isNotEmpty()) printable.toDouble() / bytes.size else 0.0
    println("   可打印 ASCII 比例: ${"%.1f".format(ratio * 100)}% ($printable/${bytes.size})")
    if (ratio > 0.5) {
        val asText = String(bytes, Charsets.UTF_8).trim()
        println("   文本预览: ${asText.take(300)}")
    }
}

fun formatTime(startMs: Long, endMs: Long): String {
    val startSec = startMs / 1000
    val startMin = startSec / 60
    val startSecRest = startSec % 60
    val startMsRest = startMs % 1000
    return "[%d:%02d.%03d]".format(startMin, startSecRest, startMsRest)
}

fun formatMs(ms: Long): String {
    return "${ms}ms"
}

/**
 * 解析并打印 QRC 歌词（用于检测到明文 QRC 时直接输出）
 */
fun parseAndPrintQrc(content: String) {
    println("═" .repeat(70))
    println("🎤 QRC 歌词内容:")
    println("═" .repeat(70))

    val lines = parseQrc(content)
    for (line in lines) {
        val timeStr = formatTime(line.startTime, line.endTime)
        val wordsDetail = if (line.words.size <= 1) {
            line.text
        } else {
            line.words.joinToString("") { w ->
                "(${w.startTime}→${w.endTime}ms)${w.word}"
            }
        }
        println("  $timeStr $wordsDetail")
    }
}

