// 步骤 7: Zlib 解压
// ═══════════════════════════════════════════════════════
println("─" .repeat(70))
println("🗜️  【步骤 7】Zlib 解压缩")
println("─" .repeat(70))

val decompressedBytes: ByteArray
try {
    // 检查是否以 0x78 开头（zlib 头）
    if (decryptedBytes.isNotEmpty() && decryptedBytes[0].toInt() and 0xFF == 0x78) {
        println("   发现 zlib 头 (0x78)，执行标准 zlib 解压...")
    } else if (decryptedBytes.isNotEmpty()) {
        println("   未发现标准 zlib 头，尝试多种解压策略...")
    }

    val decompressStart = System.currentTimeMillis()
    decompressedBytes = tryZlibDecompress(decryptedBytes)
    val decompressTime = System.currentTimeMillis() - decompressStart
    println("   解压耗时: ${decompressTime}ms")
    println("   解压后字节数: ${decompressedBytes.size}")
    println("   压缩比: ${if (decryptedBytes.isNotEmpty()) "%.2f%%".format(decompressedBytes.size.toDouble() / decryptedBytes.size * 100) else "N/A"}")
    println("   前 64 字节 (HEX): ${decompressedBytes.take(64).joinToString(" ") { "%02X".format(it) }}")
    println()

    // 检查 BOM
    if (decompressedBytes.size >= 3 &&
        decompressedBytes[0].toInt() and 0xFF == 0xEF &&
        decompressedBytes[1].toInt() and 0xFF == 0xBB &&
        decompressedBytes[2].toInt() and 0xFF == 0xBF
    ) {
        println("   ℹ️ 检测到 UTF-8 BOM (EF BB BF)，将自动移除")
    }
} catch (e: Exception) {
    println("   ❌ zlib 解压失败: $e")
    println("   可能 3DES 解密结果不是压缩数据，尝试直接作为文本处理...")
    printIfMostlyAscii(decryptedBytes)
    return
}
println()

