        val v1 = (input[4].toInt() and 0xFF) or ((input[5].toInt() and 0xFF) shl 8) or
                ((input[6].toInt() and 0xFF) shl 16) or ((input[7].toInt() and 0xFF) shl 24)

        val s0 = (
            ((v1 shr 6) and 1) shl 31 or ((v1 shr 14) and 1) shl 30 or
            ((v1 shr 22) and 1) shl 29 or ((v1 shr 30) and 1) shl 28 or
            ((v0 shr 6) and 1) shl 27 or ((v0 shr 14) and 1) shl 26 or
            ((v0 shr 22) and 1) shl 25 or ((v0 shr 30) and 1) shl 24 or
            ((v1 shr 4) and 1) shl 23 or ((v1 shr 12) and 1) shl 22 or
