suspend fun main(args: Array<String>) {
    println("=" .repeat(70))
    println("  QQ 音乐 QRC 逐字歌词获取与解密工具")
    println("  参考: L-1124/QQMusicApi")
    println("=" .repeat(70))
    println()

    // ------ 命令行参数 ------
    val songTitle = args.getOrNull(0) ?: "告白气球"
    val songArtist = args.getOrNull(1) ?: "周杰伦"
    println("🔍 目标歌曲: 「$songTitle」- $songArtist")
    println()

    val httpClient = HttpClient(CIO) {
        engine {
            requestTimeout = 30_000
        }
    }

    try {
        // ═══════════════════════════════════════════════════════
        // 步骤 1: 搜索歌曲
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📡 【步骤 1】搜索歌曲")
        println("─" .repeat(70))

        val searchResults = searchSong(httpClient, songTitle, songArtist)
        if (searchResults.isEmpty()) {
            println("❌ 未找到任何匹配的歌曲")
            return
        }

        println("\n✅ 找到 ${searchResults.size} 个结果:")
        searchResults.forEachIndexed { i, r ->
            println("   #${i + 1}: songMid=${r.songMid}, 标题=${r.title}, 歌手=${r.artist}, 时长=${r.duration}ms")
        }

        // 选择第一个结果
        val selected = searchResults.first()
        println("\n👉 选择 #1: ${selected.title} - ${selected.artist} (songMid=${selected.songMid})")
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 2: 获取歌词原始数据
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📡 【步骤 2】获取歌词原始数据")
        println("─" .repeat(70))

        val rawResponse = fetchLyricsRaw(httpClient, selected.songMid)
        println("   API 响应长度: ${rawResponse.length} 字符")
        println("   响应前 500 字符预览:")
        println("   " + rawResponse.take(500).replace("\n", "\n   "))
        println("   ... (共 ${rawResponse.length} 字符)")
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 3: 解析 JSON 并提取各个字段
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📋 【步骤 3】解析响应 JSON 各字段")
        println("─" .repeat(70))

        val responseJson = Json.parseToJsonElement(rawResponse).jsonObject

        // 提取 lyric（LRC 格式）
        val lyricContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("lyric")
            ?.jsonPrimitive?.contentOrNull

        // 提取 qrc（逐字格式，加密的 Hex 字符串）
        val qrcContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("qrc")
            ?.jsonPrimitive?.contentOrNull

        // 提取 trans（翻译）
        val transContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("trans")
            ?.jsonPrimitive?.contentOrNull

        // 提取 roma（罗马音）
        val romaContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("roma")
            ?.jsonPrimitive?.contentOrNull

        // 提取 songID（数字 ID）
        val songIdNum = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("songID")
            ?.jsonPrimitive?.longOrNull

        // 提取 crypt 标记（是否返回加密数据）
        val cryptFlag = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("crypt")
            ?.jsonPrimitive?.contentOrNull

        println("   歌曲 ID: ${songIdNum ?: "N/A"}")
        println("   crypt 标记: $cryptFlag (1=加密)")
        println("   LRC 歌词: ${if (!lyricContent.isNullOrBlank()) "✅ (长度=${lyricContent.length})" else "❌ 空"}")
        println("   QRC 标记: ${if (!qrcContent.isNullOrBlank()) "✅ ($qrcContent)" else "❌ 为空"}")
        println("   翻译:     ${if (!transContent.isNullOrBlank()) "✅ (长度=${transContent.length})" else "❌ 空"}")
        println("   罗马音:   ${if (!romaContent.isNullOrBlank()) "✅ (长度=${romaContent.length})" else "❌ 空"}")
        // 确定最终用于解密的 QRC 内容
        // 当 crypt=1 时，API 返回加密数据，lyric 字段就是加密的 QRC HEX 字符串
        // qrc 字段此时是布尔标记（"1"=有QRC，"0"=无QRC），不是实际数据
        var finalQrcContent: String? = null
