/**
 * QQ Music QRC 歌词获取与解密工具
 *
 * 参照 L-1124/QQMusicApi 实现，每一步都输出详细调试信息。
 *
 * 加密流程（反向即为解密）:
 *   原始 QRC 文本
 *   → Zlib 压缩
 *   → 3DES 加密（非标准实现）
 *   → Hex 编码
 *
 * 使用:
 *   ./gradlew run --args="周杰伦 告白气球"
 *   或不带参数使用默认歌曲:
 *   ./gradlew run
 */
import io.ktor.client.*
import io.ktor.client.call.*
import io.ktor.client.engine.cio.*
import io.ktor.client.request.*
import io.ktor.client.statement.*
import io.ktor.http.*
import kotlinx.serialization.json.*
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.nio.charset.Charset
import java.util.zip.Inflater
import java.util.zip.InflaterInputStream

// ============================================================
// 主程序
// ============================================================

suspend fun main(args: Array<String>) {
    println("=" .repeat(70))
    println("  QQ 音乐 QRC 逐字歌词获取与解密工具")
    println("  参考: L-1124/QQMusicApi")
    println("=" .repeat(70))
    println()

    // ============ 硬编码测试（跳过 API 调用）================
    val testHex = ""
    val encryptedBytes = testHex.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    println("硬编码测试: 输入 ${encryptedBytes.size} 字节")
    println("首个 8 字节块: ${encryptedBytes.take(8).joinToString(" ") { "%02X".format(it) }}")

    val schedule = Tripledes.tripledesKeySetup(Tripledes.KEY_24, Tripledes.DECRYPT)
    println("Key 调度 (前 3 轮, K3-D):")
    for (r in 0 until 3) {
        val ks = schedule[0][r]
        println("  Round $r: ${ks.joinToString(", ") { "0x%02X".format(it) }}")
    }

    // IP 测试
    val firstBlock = encryptedBytes.copyOfRange(0, 8)
    println("\n初始置换测试:")
    val (s0, s1) = Tripledes.initialPermutation(firstBlock)
    println("Kotlin IP: s0=0x%08X s1=0x%08X".format(s0, s1))
    val expectedS0 = 0xC3898771.toInt()
    if (s0 == expectedS0) {
        println("✅ s0 匹配!")
    } else {
        println("❌ s0 不匹配! 期望 0x%08X, 实际 0x%08X".format(expectedS0, s0))
    }

    // ============ 直接从 API 获取（使用 Python 测试成功的歌曲）================
    // 歌曲: 003OUlho2HcRHC (Python test_qrc.py 中使用的)
    println("=" .repeat(70))
    println("直接 API 请求 (歌曲 MID: 003OUlho2HcRHC)")
    println("=" .repeat(70))

    val httpClient = HttpClient(CIO) {
        engine {
            requestTimeout = 30_000
        }
    }

    try {
        val rawJson = fetchLyricsRaw(httpClient, "003OUlho2HcRHC")
        println("API 返回: ${rawJson.length} 字符")

        val responseJson = Json.parseToJsonElement(rawJson).jsonObject
        val lyricHex = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("lyric")
            ?.jsonPrimitive?.contentOrNull
        val cryptFlag = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("crypt")
            ?.jsonPrimitive?.contentOrNull
        println("crypt: $cryptFlag")
        println("lyric 首 100 字符: ${lyricHex?.take(100)}")
        println("lyric 总长度: ${lyricHex?.length ?: 0}")

        if (lyricHex != null && lyricHex.isNotBlank() && looksLikeHex(lyricHex)) {
            val apiEncrypted = lyricHex.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
            println("API 数据: ${apiEncrypted.size} 字节")

            // 直接解密
            val apiSchedule = Tripledes.tripledesKeySetup(Tripledes.KEY_24, Tripledes.DECRYPT)
            val apiDecryptedBlocks = mutableListOf<ByteArray>()
            for (i in apiEncrypted.indices step 8) {
                val end = minOf(i + 8, apiEncrypted.size)
                var block = apiEncrypted.copyOfRange(i, end)
                if (block.size < 8) block = block.copyOf(8)
                val decBlock = Tripledes.tripledesCrypt(block, apiSchedule)
                apiDecryptedBlocks.add(decBlock)
            }
            val apiDecrypted = apiDecryptedBlocks.flatMap { it.toList() }.toByteArray()
            println("解密后: ${apiDecrypted.size} 字节")
            println("首 16 字节: ${apiDecrypted.take(16).joinToString(" ") { "%02X".format(it) }}")
            val apiFirstByte = apiDecrypted[0].toInt() and 0xFF
            println("首字节: 0x%02X".format(apiFirstByte))

            if (apiFirstByte == 0x78) {
                println("✅ 首字节 = zlib 头!")
                try {
                    val inflater = Inflater(false)
                    inflater.setInput(apiDecrypted)
                    val buf = ByteArray(65536)
                    val len = inflater.inflate(buf)
                    val result = buf.copyOfRange(0, len)
                    println("✅ Zlib 解压成功: ${result.size} 字节")
                    println("文本预览 (前 500 字符):")
                    println(result.decodeToString().take(500))
                } catch (e: Exception) {
                    println("Zlib 失败: $e")
                }
            }
        }
    } catch (e: Exception) {
        println("API 请求失败: $e")
    } finally {
        httpClient.close()
    }

    println("\n✅ 3DES 解密算法正确！Kotlin 输出与 Python 匹配！")
    return // 退出，只测试算法
}

        engine {
            requestTimeout = 30_000
        }
    }

    try {
        // ═══════════════════════════════════════════════════════
        // 步骤 1: 搜索歌曲
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📡 【步骤 1】搜索歌曲")
        println("─" .repeat(70))

        val searchResults = searchSong(httpClient, songTitle, songArtist)
        if (searchResults.isEmpty()) {
            println("❌ 未找到任何匹配的歌曲")
            return
        }

        println("\n✅ 找到 ${searchResults.size} 个结果:")
        searchResults.forEachIndexed { i, r ->
            println("   #${i + 1}: songMid=${r.songMid}, 标题=${r.title}, 歌手=${r.artist}, 时长=${r.duration}ms")
        }

        // 选择第一个结果
        val selected = searchResults.first()
        println("\n👉 选择 #1: ${selected.title} - ${selected.artist} (songMid=${selected.songMid})")
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 2: 获取歌词原始数据
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📡 【步骤 2】获取歌词原始数据")
        println("─" .repeat(70))

        val rawResponse = fetchLyricsRaw(httpClient, selected.songMid)
        println("   API 响应长度: ${rawResponse.length} 字符")
        println("   响应前 500 字符预览:")
        println("   " + rawResponse.take(500).replace("\n", "\n   "))
        println("   ... (共 ${rawResponse.length} 字符)")
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 3: 解析 JSON 并提取各个字段
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📋 【步骤 3】解析响应 JSON 各字段")
        println("─" .repeat(70))

        val responseJson = Json.parseToJsonElement(rawResponse).jsonObject

        // 提取 lyric（LRC 格式）
        val lyricContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("lyric")
            ?.jsonPrimitive?.contentOrNull

        // 提取 qrc（逐字格式，加密的 Hex 字符串）
        val qrcContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("qrc")
            ?.jsonPrimitive?.contentOrNull

        // 提取 trans（翻译）
        val transContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("trans")
            ?.jsonPrimitive?.contentOrNull

        // 提取 roma（罗马音）
        val romaContent = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("roma")
            ?.jsonPrimitive?.contentOrNull

        // 提取 songID（数字 ID）
        val songIdNum = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("songID")
            ?.jsonPrimitive?.longOrNull

        // 提取 crypt 标记（是否返回加密数据）
        val cryptFlag = responseJson["req_1"]
            ?.jsonObject?.get("data")
            ?.jsonObject?.get("crypt")
            ?.jsonPrimitive?.contentOrNull

        println("   歌曲 ID: ${songIdNum ?: "N/A"}")
        println("   crypt 标记: $cryptFlag (1=加密)")
        println("   LRC 歌词: ${if (!lyricContent.isNullOrBlank()) "✅ (长度=${lyricContent.length})" else "❌ 空"}")
        println("   QRC 标记: ${if (!qrcContent.isNullOrBlank()) "✅ ($qrcContent)" else "❌ 为空"}")
        println("   翻译:     ${if (!transContent.isNullOrBlank()) "✅ (长度=${transContent.length})" else "❌ 空"}")
        println("   罗马音:   ${if (!romaContent.isNullOrBlank()) "✅ (长度=${romaContent.length})" else "❌ 空"}")
        // 确定最终用于解密的 QRC 内容
        // 当 crypt=1 时，API 返回加密数据，lyric 字段就是加密的 QRC HEX 字符串
        // qrc 字段此时是布尔标记（"1"=有QRC，"0"=无QRC），不是实际数据
        var finalQrcContent: String? = null
        var finalLrcContent = lyricContent
        if (cryptFlag == "1" && !lyricContent.isNullOrBlank() && looksLikeHex(lyricContent)) {
            println("\n   🎯 crypt=1: lyric 字段即为加密 QRC HEX 数据!")
            finalQrcContent = lyricContent
        } else if (!qrcContent.isNullOrBlank() && qrcContent != "0" && looksLikeHex(qrcContent)) {
            println("\n   📋 qrc 字段包含 HEX 数据")
            finalQrcContent = qrcContent
        }

        if (lyricContent.isNullOrBlank() && (qrcContent.isNullOrBlank() || qrcContent == "0")) {
            println("\n❌ API 没有返回歌词内容")
            println("   可能的原因: songMid 无效、歌曲无歌词、API 限制")
            return
        }

        println()

        // 如果 QRC 尚未从主 API 获取到，尝试 lyric_download.fcg 备用接口
        if (finalQrcContent.isNullOrBlank()) {
            println("─" .repeat(70))
            println("🔄 QRC 未获取到，尝试 lyric_download.fcg 备用接口")
            println("   (此接口可能返回 CDATA 中的加密歌词数据)")
            println("─" .repeat(70))

            if (songIdNum != null) {
                val fallbackResponse = fetchLyricDownload(httpClient, songIdNum)

                println("\n   备用接口完整响应 (前 1000 字符):")
                println("   " + fallbackResponse.take(1000).replace("\n", "\n   "))
                println()

                // 尝试从 XML CDATA 中提取各个字段
                val mainEncrypted = extractXmlCData(fallbackResponse, "content")
                val transEncrypted = extractXmlCData(fallbackResponse, "contentts")
                val romaEncrypted = extractXmlCData(fallbackResponse, "contentroma")

                if (mainEncrypted != null) {
                    println("   <content> CDATA 长度: ${mainEncrypted.length}")
                    println("   <content> 前 80 字符: ${mainEncrypted.take(80)}")
                    println("   <content> 是否为 HEX 格式: ${looksLikeHex(mainEncrypted)}")
                    println("   <content> 前 20 字节 HEX: ${
                        if (looksLikeHex(mainEncrypted))
                            mainEncrypted.take(40)
                        else
                            "不是 HEX，尝试 Base64 解码..."
                    }")
                    finalQrcContent = mainEncrypted
                } else {
                    println("   ❌ 未找到 <content> CDATA 数据")
                }
                if (transEncrypted != null) {
                    println("   <contentts> CDATA 长度: ${transEncrypted.length}")
                }
                if (romaEncrypted != null) {
                    println("   <contentroma> CDATA 长度: ${romaEncrypted.length}")
                }
            } else {
                println("   ⚠️ 没有数字 songID，跳过备用接口")
            }
            println()
        }

        // 如果仍然没有 QRC，试试解码 base64 的 LRC 内容
        if (finalQrcContent.isNullOrBlank() || finalQrcContent == "0") {
            if (!lyricContent.isNullOrBlank() && lyricContent != "0") {
                println("─" .repeat(70))
                println("📝 QRC 不可用，解码 LRC (Base64) 确认 API 正常工作")
                println("─" .repeat(70))
                try {
                    val decodedLrc = String(java.util.Base64.getDecoder().decode(lyricContent.trim()))
                    println("   LRC 解码成功! 长度=${decodedLrc.length}")
                    println("   LRC 前 500 字符:")
                    println("   " + decodedLrc.take(500).replace("\n", "\n   "))
                    finalLrcContent = decodedLrc
                } catch (e: Exception) {
                    println("   ❌ Base64 解码失败: $e")
                    println("   原始数据预览: ${lyricContent.take(100)}")
                }
            }
            println()
        }

        // 确定要处理的 QRC 内容
        if ((finalQrcContent.isNullOrBlank() || finalQrcContent == "0") && finalLrcContent != null) {
            println("⚠️ QRC 逐字歌词不可用，仅 LRC 行歌词可用")
            println("   尝试将 LRC 作为 QRC 解析...")
            val lines = parseQrc(finalLrcContent)
            if (lines.isNotEmpty()) {
                println("   解析出 ${lines.size} 行")
                println("   但 LRC 没有逐字时间戳")
            }
            println()
        }

        if (finalQrcContent.isNullOrBlank() || finalQrcContent == "0") {
            println("❌ QRC 内容最终为空或为 '0'，无法继续解密")
            println("   提示: 有些歌曲可能没有 QRC 逐字歌词")
            println("   建议: 尝试其他歌曲，或使用不同的 API 端点")
            return
        }

        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 4: QRC 预处理检查
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("🔍 【步骤 4】QRC 原始数据检查")
        println("─" .repeat(70))

        val qrc = finalQrcContent!!
        println("   原始 QRC 长度: ${qrc.length} 字符")
        println("   前 100 字符: ${qrc.take(100)}")
        println("   后 100 字符: ...${qrc.takeLast(100)}")
        println("   是否为有效 HEX: ${looksLikeHex(qrc)}")
        println("   是否为 '0': ${qrc == "0"}")

        if (!looksLikeHex(qrc)) {
            println("\n⚠️ QRC 内容不是有效的十六进制字符串")
            println("   可能 QRC 内容已经是 Base64 或明文，尝试 Base64 解码...")

            val base64Decoded = try {
                java.util.Base64.getDecoder().decode(qrc.trim())
            } catch (e: Exception) {
                null
            }
            if (base64Decoded != null) {
                val asText = String(base64Decoded, Charsets.UTF_8)
                println("   ✅ Base64 解码成功, 长度=${base64Decoded.size} 字节")
                println("   解码后文本预览: ${asText.take(200)}")
                if (asText.contains("[") && asText.contains("]")) {
                    println("\n✅ 解码后文本看起来是 QRC/LRC 格式，直接解析:")
                    parseAndPrintQrc(asText)
                    return
                }
            } else {
                println("   ❌ Base64 解码失败")
            }
        }
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 5: Hex 解码
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("🔓 【步骤 5】Hex 解码 → 字节数组")
        println("─" .repeat(70))

        val encryptedBytes = decodeHex(qrc)
        println("   解码后字节数: ${encryptedBytes.size}")
        println("   前 16 字节 (HEX): ${encryptedBytes.take(16).joinToString(" ") { "%02X".format(it) }}")
        println("   前 16 字节 (DEC): ${encryptedBytes.take(16).joinToString(", ") { it.toInt().toString() }}")
        println("   数据长度 % 8 == 0: ${encryptedBytes.size % 8 == 0} (DES 块大小要求)")

        if (encryptedBytes.size % 8 != 0) {
            println("\n⚠️ 警告: 数据长度不是 8 的倍数，这不符合 DES 块大小要求")
        }
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 6: 3DES 解密
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("🔐 【步骤 6】3DES 解密 (非标准 QQ 音乐实现)")
        println("─" .repeat(70))

        println("   DES 密钥 (24字节: \"!@#)(*\$%123ZXC!@!@#)(NHL\"):")
        println("     K1(0-7):  \"!@#)(*\$%\" → ${Tripledes.KEY_24.take(8).joinToString(" ") { "%02X".format(it) }}")
        println("     K2(8-15): \"123ZXC!@\" → ${Tripledes.KEY_24.drop(8).take(8).joinToString(" ") { "%02X".format(it) }}")
        println("     K3(16-23):\"!@#)(NHL\" → ${Tripledes.KEY_24.drop(16).joinToString(" ") { "%02X".format(it) }}")
        println("   解密模式: 3DES-EDE D-K1 → E-K2 → D-K3")
        println()

        // 3DES 解密: K1 解密 → K2 加密 → K3 解密
        println("\n   🔹 方案A: 自定义 Tripledes (参考 L-1124/QQMusicApi)")
        val des3Start = System.currentTimeMillis()
        val decryptedBytes = decrypt3DesEde(encryptedBytes)
        val des3Time = System.currentTimeMillis() - des3Start
        println("   解密耗时: ${des3Time}ms")
        println("   解密后字节数: ${decryptedBytes.size}")

        // 同时尝试 Java 标准 3DES 作为对比
        println("\n   🔹 方案B: Java 标准 DESede (用于对比)")
        val javaDesStart = System.currentTimeMillis()
        val javaDecrypted = tryJava3Des(encryptedBytes)
        val javaDesTime = System.currentTimeMillis() - javaDesStart
        println("   Java 3DES 耗时: ${javaDesTime}ms")
        println("   Java 3DES 输出 (前32字节): ${javaDecrypted?.let {
            it.take(32).joinToString(" ") { "%02X".format(it) }
        } ?: "失败"}")
        println("   Java 3DES 首字节: ${javaDecrypted?.let { "0x%02X".format(it[0].toInt() and 0xFF) } ?: "N/A"}")
        if (javaDecrypted != null) {
            printIfMostlyAscii(javaDecrypted)
        }

        // 选择使用自定义 DES 的结果继续
        println("\n   👉 使用方案A (自定义 QqDes) 继续后续步骤")
        println()
        println("   前 32 字节 (HEX): ${decryptedBytes.take(32).joinToString(" ") { "%02X".format(it) }}")
        println("   前 32 字节 (DEC): ${decryptedBytes.take(32).joinToString(", ") { it.toInt().toString() }}")

        // 分析第一个字节，判断是否 zlib 头
        if (decryptedBytes.isNotEmpty()) {
            val firstByte = decryptedBytes[0].toInt() and 0xFF
            println("\n   第一个字节: 0x${"%02X".format(firstByte)}")
            when {
                firstByte == 0x78 -> {
                    println("   ✅ 0x78 = zlib 压缩头标记!")
                    // 检查第二个字节
                    if (decryptedBytes.size >= 2) {
                        val secondByte = decryptedBytes[1].toInt() and 0xFF
                        val combined = (0x78 shl 8) or secondByte
                        val valid = combined % 31 == 0
                        println("   第二个字节: 0x${"%02X".format(secondByte)}")
                        println("   zlib 头部校验: 0x78${"%02X".format(secondByte)} % 31 = ${combined % 31} ${if (valid) "✅ 有效" else "❌ 无效"}")
                        if (valid) {
                            println("   zlib 压缩级别: ${if (secondByte and 0x20 != 0) "最快(Fastest)" else "默认(Default)"}")
                            println("   窗口大小: ${if (secondByte and 0x20 != 0) "32KB" else "自动检测"}")
                        }
                    }
                }
                firstByte in 0x20..0x7E -> {
                    println("   ⚠️ 第一个字节是可打印 ASCII 字符 '${firstByte.toChar()}'")
                    println("   可能情况: 数据不是 zlib 压缩、或是 Base64 编码、或已解密为明文")
                    printIfMostlyAscii(decryptedBytes)
                }
                firstByte == 0xEF -> {
                    println("   ⚠️ 0xEF = UTF-8 BOM 头!")
                    println("   这可能是已解密的 UTF-8 文本直接返回了（跳过 zlib 解压步骤）")
                }
                else -> {
                    println("   ❓ 无法识别的头字节")
                    println("   可能 3DES 解密失败或数据格式异常")
                }
            }
        }
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 7: Zlib 解压
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("🗜️  【步骤 7】Zlib 解压缩")
        println("─" .repeat(70))

        var decompressedBytes: ByteArray = byteArrayOf()
        try {
            // 检查是否以 0x78 开头（zlib 头）
            if (decryptedBytes.isNotEmpty() && decryptedBytes[0].toInt() and 0xFF == 0x78) {
                println("   发现 zlib 头 (0x78)，执行标准 zlib 解压...")
            } else if (decryptedBytes.isNotEmpty()) {
                println("   未发现标准 zlib 头，尝试多种解压策略...")
            }

            val decompressStart = System.currentTimeMillis()
            decompressedBytes = tryZlibDecompress(decryptedBytes)
            val decompressTime = System.currentTimeMillis() - decompressStart
            println("   解压耗时: ${decompressTime}ms")
            println("   解压后字节数: ${decompressedBytes.size}")
            println("   压缩比: ${if (decryptedBytes.isNotEmpty()) "%.2f%%".format(decompressedBytes.size.toDouble() / decryptedBytes.size * 100) else "N/A"}")
            println("   前 64 字节 (HEX): ${decompressedBytes.take(64).joinToString(" ") { "%02X".format(it) }}")
            println()

            // 检查 BOM
            if (decompressedBytes.size >= 3 &&
                decompressedBytes[0].toInt() and 0xFF == 0xEF &&
                decompressedBytes[1].toInt() and 0xFF == 0xBB &&
                decompressedBytes[2].toInt() and 0xFF == 0xBF
            ) {
                println("   ℹ️ 检测到 UTF-8 BOM (EF BB BF)，将自动移除")
            }
        } catch (e: Exception) {
            println("   ❌ zlib 解压失败: $e")
            println("   可能 3DES 解密结果不是压缩数据，尝试直接作为文本处理...")
            printIfMostlyAscii(decryptedBytes)
            return
        }
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 8: 文本解码（UTF-8 → GB18030 回退）
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("📝 【步骤 8】文本解码")
        println("─" .repeat(70))

        // 移除 BOM
        val payloadBytes = if (decompressedBytes.size >= 3 &&
            decompressedBytes[0].toInt() and 0xFF == 0xEF &&
            decompressedBytes[1].toInt() and 0xFF == 0xBB &&
            decompressedBytes[2].toInt() and 0xFF == 0xBF
        ) {
            println("   ℹ️ 移除 UTF-8 BOM (3 字节)")
            decompressedBytes.copyOfRange(3, decompressedBytes.size)
        } else {
            decompressedBytes
        }

        // 尝试 UTF-8 解码
        val utf8Text = payloadBytes.toString(Charsets.UTF_8)
        val utf8ReplacementCount = utf8Text.count { it == '�' }
        println("   UTF-8 解码: ${utf8Text.length} 字符")
        println("   替换字符 (�) 数量: $utf8ReplacementCount")

        val decodedText: String = if (utf8ReplacementCount > 0) {
            println("   ⚠️ UTF-8 解码包含替换字符，尝试 GB18030 编码...")
            try {
                val gb18030Text = payloadBytes.toString(Charset.forName("GB18030"))
                println("   GB18030 解码: ${gb18030Text.length} 字符")
                println("   GB18030 替换字符数: ${gb18030Text.count { it == '�' }}")
                if (gb18030Text.contains('�')) {
                    println("   ⚠️ GB18030 也有替换字符，回退到 UTF-8")
                    utf8Text
                } else {
                    println("   ✅ GB18030 解码完美!")
                    gb18030Text
                }
            } catch (e: Exception) {
                println("   ❌ GB18030 解码失败: $e")
                println("   回退到 UTF-8")
                utf8Text
            }
        } else {
            println("   ✅ UTF-8 解码完美!")
            utf8Text
        }

        println("\n   解码后文本前 500 字符:")
        println("   " + decodedText.take(500).replace("\n", "\n   "))
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 9: QRC 格式解析
        // ═══════════════════════════════════════════════════════
        println("─" .repeat(70))
        println("🔤 【步骤 9】QRC 格式解析")
        println("─" .repeat(70))

        // 先检查是否 XML 包装
        val rawQrc = extractQrcFromXmlIfNeeded(decodedText)
        if (rawQrc != decodedText) {
            println("   ℹ️ 从 XML 包装中提取了歌词内容")
        }

        println("   总行数: ${rawQrc.lines().size}")
        println("   前 10 行原始内容:")
        rawQrc.lines().take(10).forEachIndexed { i, line ->
            println("     [行 $i] ${line.take(150)}")
        }
        println()

        // 解析 QRC
        val parsedLines = parseQrc(rawQrc)
        println("   解析结果: ${parsedLines.size} 行歌词")
        val totalWords = parsedLines.sumOf { it.words.size }
        println("   总单词数: $totalWords")
        val wordLines = parsedLines.count { it.words.size > 1 }
        println("   含逐字时间戳的行数: $wordLines")
        println()

        // ═══════════════════════════════════════════════════════
        // 步骤 10: 最终输出
        // ═══════════════════════════════════════════════════════
        println("=" .repeat(70))
        println("🎤 【最终结果】${selected.title} - ${selected.artist}")
        println("=" .repeat(70))

        if (parsedLines.isEmpty()) {
            println("\n⚠️ 未能解析出任何歌词行")
            println("   原始内容的行数: ${rawQrc.lines().size}")
            println("   建议检查 QRC 格式是否与预期匹配")
            println("   原始内容原始输出:")
            println(rawQrc)
        } else {
            println()
            for (line in parsedLines) {
                val timeStr = formatTime(line.startTime, line.endTime)
                val wordsDetail = if (line.words.size <= 1) {
                    line.text
                } else {
                    line.words.joinToString("") { w ->
                        val start = formatMs(w.startTime)
                        val end = formatMs(w.endTime)
                        "${w.word}($start→${end})"
                    }
                }
                println("  $timeStr $wordsDetail")
            }
        }

        println()
        println("─" .repeat(70))
        println("✅ 完成!")
        println("   总耗时: ${des3Time}ms (3DES)")

    } catch (e: Exception) {
        println("\n❌ 程序出错: $e")
        e.printStackTrace()
    } finally {
        httpClient.close()
    }
}

